package list

import "testing"

func TestJoinList(t *testing.T) {
	cases := []struct {
		in   []string
		want string
	}{
		{nil, ""},
		{[]string{"single"}, "single"},
		{[]string{"a", "b"}, "a, b"},
		{[]string{"a", "b", "c"}, "a, b, c"},
	}
	for _, c := range cases {
		if got := JoinList(c.in); got != c.want {
			t.Errorf("JoinList(%q) = %q, want %q", c.in, got, c.want)
		}
	}
}

func TestJoinListParseListRoundTrip(t *testing.T) {
	items := []string{"a", "b", "c"}
	if got := ParseList(JoinList(items)); !equalSlices(got, items) {
		t.Errorf("ParseList(JoinList(%q)) = %q, want %q", items, got, items)
	}
}

func equalSlices(a, b []string) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

